/**
 * RankedChart -- Lead Panel Chart view. THE CHART IS OVER TIME.
 *
 * AMGT-re-1 GAP 4, verbatim from the FAIL grade: "RankedChart is ticker-indexed and
 * has no time-series implementation despite the stated automatic second-day
 * behavior." It is no longer ticker-indexed. The X axis is `as_of_date` and each
 * ticker is a LINE across it; a ticker is a series identity, never a category on the
 * X axis.
 *
 * WHY IT STARTS WORKING ON DAY TWO BY ITSELF. The series come from
 * `/api/scoped/amgt/lead-panel/timeseries/...`, which point-reads one item per
 * `axis_date` in a 30-day window. AMGT-rd-5 writes a new `axis_date` every day, so
 * the number of X positions with data grows by one per daily run with NO code change
 * and NO flag here or on the server. Today exactly one `axis_date` has landed per
 * subject, so each line has ONE point -- and a single point is the honest render of
 * one day, not a defect to be hidden. The point count per ticker is printed beside
 * the legend so the reader can see the denominator rather than infer it from a flat
 * line.
 *
 * NOTHING IS RE-DERIVED. `rank` and `score` are the producer's own values, carried
 * verbatim. The only transform below is a PIVOT -- the same points re-keyed by date
 * so recharts can read them -- plus a chronological ordering that is the X axis, not
 * a ranking. No comparator touches `rank` or `score`.
 *
 * Y AXIS IS REVERSED: rank 1 is the top of the chart, which is how a rank reads.
 * That is a scale direction, not a re-ordering of data.
 *
 * Dark-container-only (white idiom) -- rendered inside `LeadPanel`'s
 * `Panel variant="mixed"` body (recharts' own SVG text uses an explicit fill, not a
 * Tailwind text-white class, so it is set per-element below).
 */

import { type FC } from 'react'
import {
  CartesianGrid,
  Legend,
  Line,
  LineChart,
  ResponsiveContainer,
  Tooltip,
  XAxis,
  YAxis,
} from 'recharts'
import type { RankTimeSeriesSet } from '../types'

export interface RankedChartProps {
  data: RankTimeSeriesSet | undefined
  isLoading?: boolean
}

const AXIS_TEXT_FILL = 'rgba(255,255,255,0.5)'
const GRID_STROKE = 'rgba(255,255,255,0.1)'

/** Line colours. A fixed palette indexed by series position -- the position comes
 * from the producer's own row order, so this assigns no meaning of its own. */
const SERIES_STROKES = [
  'hsl(var(--semantic-action-primary))',
  '#f59e0b',
  '#34d399',
  '#f472b6',
  '#60a5fa',
]

/** The PIVOT: {ticker -> points} becomes [{as_of_date, TICKER: rank, ...}], the row
 * shape recharts reads. Dates are collected from the points themselves and ordered
 * chronologically (ISO dates sort chronologically as strings) -- that ordering is
 * the X axis. No rank or score is compared, combined or recomputed. */
function pivotByDate(data: RankTimeSeriesSet): Record<string, string | number>[] {
  const dates = new Set<string>()
  data.series.forEach((series) => series.points.forEach((point) => dates.add(point.as_of_date)))
  return Array.from(dates)
    .sort()
    .map((date) => {
      const row: Record<string, string | number> = { as_of_date: date }
      data.series.forEach((series) => {
        const point = series.points.find((candidate) => candidate.as_of_date === date)
        if (point) row[series.ticker] = point.rank
      })
      return row
    })
}

export const RankedChart: FC<RankedChartProps> = ({ data, isLoading }) => {
  if (isLoading) {
    return <div className="text-sm text-white/50 py-4">Loading rank history...</div>
  }

  if (!data || data.series.length === 0) {
    return (
      <div className="text-sm text-white/50 py-4">
        No ranked names to chart for this combination yet.
      </div>
    )
  }

  const chartData = pivotByDate(data)
  const landedDates = chartData.length
  const maxRank = data.series.reduce(
    (worst, series) =>
      series.points.reduce((inner, point) => (point.rank > inner ? point.rank : inner), worst),
    1
  )

  return (
    <div>
      <div className="text-[10px] text-white/40 mb-2">
        Rank over time, {data.series.length} name(s) across {landedDates} landed{' '}
        {landedDates === 1 ? 'day' : 'days'} of a {data.window_days}-day window. Lower is
        better; rank 1 is the top of the chart.
        {landedDates === 1 &&
          ' One daily run has landed, so each line is a single point -- a second point appears on the next run, with no change here.'}
      </div>

      {landedDates > 0 && (
        <ResponsiveContainer width="100%" height={240}>
          <LineChart data={chartData} margin={{ top: 8, right: 8, left: 0, bottom: 8 }}>
            <CartesianGrid strokeDasharray="3 3" stroke={GRID_STROKE} />
            <XAxis
              dataKey="as_of_date"
              tick={{ fill: AXIS_TEXT_FILL, fontSize: 10 }}
              interval={0}
              angle={-35}
              textAnchor="end"
              height={54}
            />
            <YAxis
              reversed
              allowDecimals={false}
              domain={[1, maxRank]}
              tick={{ fill: AXIS_TEXT_FILL, fontSize: 10 }}
              label={{
                value: 'rank',
                angle: -90,
                position: 'insideLeft',
                fill: AXIS_TEXT_FILL,
                fontSize: 10,
              }}
            />
            <Tooltip
              contentStyle={{
                background: 'hsl(var(--bg-header))',
                border: '1px solid rgba(255,255,255,0.1)',
              }}
              labelStyle={{ color: 'white' }}
              itemStyle={{ color: 'white' }}
            />
            <Legend wrapperStyle={{ fontSize: 10, color: AXIS_TEXT_FILL }} />
            {data.series.map((series, index) => (
              <Line
                key={series.ticker}
                type="monotone"
                dataKey={series.ticker}
                stroke={SERIES_STROKES[index % SERIES_STROKES.length]}
                strokeWidth={2}
                dot={{ r: 3 }}
                connectNulls
                isAnimationActive={false}
              />
            ))}
          </LineChart>
        </ResponsiveContainer>
      )}

      {/* Point-count denominator per series -- readable without a browser, so the
          honest one-day state is visible in a static render too. */}
      <ul className="mt-2 flex flex-wrap gap-x-4 gap-y-1">
        {data.series.map((series, index) => (
          <li key={series.ticker} className="flex items-center gap-1.5 text-[10px] text-white/50">
            <span
              className="inline-block h-2 w-2 rounded-full"
              style={{ background: SERIES_STROKES[index % SERIES_STROKES.length] }}
            />
            {series.ticker}: {series.point_count} point(s)
          </li>
        ))}
      </ul>
    </div>
  )
}

