/**
 * LeadPanel -- the persistent universe-discovery panel.
 *
 * PERSISTENT: rendered once by `SecurityAnalysis.tsx`, above the tab bar; it stays
 * mounted while Thesis/Peers/Coverage change beneath it (task order BLOCK).
 *
 * AMGT-re-1 GAP 1 -- CROSSED CONTROLS, NOT A ONE-TO-ONE MAPPING. The panel carries
 * TWO INDEPENDENT pickers:
 *
 *     MOVEMENT   Trending | Breakout        (how the name is moving)
 *          x
 *     SUBJECT    Chatter  | Price           (what is moving)
 *
 * Either can be changed without touching the other, so all
 * `MOVEMENT_OPTIONS.length * SUBJECT_OPTIONS.length` = 4 combinations are reachable:
 * Trending x Chatter, Trending x Price, Breakout x Chatter, Breakout x Price. That is
 * the framework doc's own shape ("TWO ORTHOGONAL AXES on the Summary side:
 * `(Trending | Breakout)` x `(Price | Chatter)` ... the same four combinations Andrew
 * named", AMGT_RESAPP_FRONTEND_FRAMEWORK_20260911.md s.2). The previous cut had ONE
 * dropdown whose three values collapsed the cross into a pair of labels; there is no
 * such control in this file.
 *
 * WHAT THE CROSS MEANS ON THE WIRE: the two values become two path segments of one
 * pre-computed partition read (`/lead-panel/rankings/<movement>/<subject>`). The
 * server resolves them to a producer partition and returns the RESOLUTION beside the
 * rows; this panel renders that resolution verbatim, so when a crossed partition is
 * not yet written the reader is told which partition served instead rather than
 * shown a silently collapsed list.
 *
 * Starred is a FILTER TOGGLE over the selected combination (gap 3), not a third mode.
 * List/Chart is a display toggle within the selection. A ticker search enters
 * Security mode, the higher Summary-vs-Security split. Refresh is an explicit action,
 * NOT wired to starring.
 *
 * NO RANKING IS DERIVED HERE. The only array operations in this file are reading
 * `rows` straight through to the renderer and taking the HEAD of the already-ordered
 * list for the chart's overlay set.
 *
 * Dark-container-only (white idiom): this whole panel is `Panel variant="mixed"`.
 */

import { type FC, type FormEvent } from 'react'
import { LayoutList, LineChart as ChartIcon, RefreshCw, Search, Star } from 'lucide-react'
import { Panel, PanelHeader, PanelContent } from '@/ui/components/panels'
import { Select } from '@/ui/components/Select'
import { useAuth } from '@/hooks/useAuth'
import {
  useLeadPanelRankings,
  useRankTimeSeries,
  useStarredList,
  useSetStarred,
  useRequestRefresh,
  useSecurityOverlay,
} from '../hooks/useLeadPanelApi'
import type { LeadPanelView } from '../hooks/useSecurityAnalysisState'
import { MOVEMENT_OPTIONS, SUBJECT_OPTIONS, RANK_SERIES_TOP_N } from '../constants'
import type { MovementControl, SubjectControl, AxisResolution } from '../types'
import { RankedList } from './RankedList'
import { RankedChart } from './RankedChart'
import { StarredList } from './StarredList'
import { SecurityOverlay } from './SecurityOverlay'

export interface LeadPanelProps {
  movement: MovementControl
  setMovement: (movement: MovementControl) => void
  subject: SubjectControl
  setSubject: (subject: SubjectControl) => void
  starredOnly: boolean
  setStarredOnly: (starredOnly: boolean) => void
  view: LeadPanelView
  setView: (view: LeadPanelView) => void
  selectedSecurityKey: string | null
  onSelectSecurity: (securityKey: string) => void
  onClearSecuritySelection: () => void
  searchInput: string
  setSearchInput: (v: string) => void
}

function movementLabel(movement: MovementControl): string {
  return MOVEMENT_OPTIONS.find((option) => option.value === movement)?.label ?? movement
}

function subjectLabel(subject: SubjectControl): string {
  return SUBJECT_OPTIONS.find((option) => option.value === subject)?.label ?? subject
}

/** The resolution line. Renders inside the dark panel body, never loose on the
 * canvas, and always says which partition actually served the rows. */
const ResolutionNote: FC<{ resolution: AxisResolution | undefined }> = ({ resolution }) => {
  if (!resolution) return null
  if (resolution.resolution === 'CROSSED') {
    return (
      <div className="text-[10px] text-white/40 mb-2">
        Served by the producer partition {resolution.served_axis} (movement dimension:
        MEASURED).
      </div>
    )
  }
  return (
    <div className="text-[10px] text-amber-300/80 mb-2">
      No producer has written {resolution.requested_axis} yet -- these rows are the{' '}
      {resolution.served_axis} partition (movement dimension: ABSENT). The combination
      you picked is the one that will be served the day that partition lands.
    </div>
  )
}

export const LeadPanel: FC<LeadPanelProps> = ({
  movement,
  setMovement,
  subject,
  setSubject,
  starredOnly,
  setStarredOnly,
  view,
  setView,
  selectedSecurityKey,
  onSelectSecurity,
  onClearSecuritySelection,
  searchInput,
  setSearchInput,
}) => {
  const { claims } = useAuth()
  const firmId = claims?.firmId ?? undefined

  // ONE read for the SELECTED combination -- both controls are arguments.
  const rankingQuery = useLeadPanelRankings(movement, subject)
  const rows = rankingQuery.data?.rows ?? []
  const resolution = rankingQuery.data?.resolution

  const starredQuery = useStarredList(firmId)
  const setStarredMutation = useSetStarred(firmId)
  const refreshMutation = useRequestRefresh()
  const overlayQuery = useSecurityOverlay(selectedSecurityKey)

  const starredTickers = new Set((starredQuery.data ?? []).map((entry) => entry.ticker))

  // The chart overlays the HEAD of the producer's already-ordered rows. Taking the
  // first N of a pre-sorted list is a bound, not a selection computed here.
  const chartTickers = rows.slice(0, RANK_SERIES_TOP_N).map((row) => row.ticker)
  const seriesQuery = useRankTimeSeries(movement, subject, chartTickers)

  const handleToggleStar = (ticker: string) => {
    setStarredMutation.mutate({ ticker, starred: !starredTickers.has(ticker) })
  }

  const handleSearchSubmit = (e: FormEvent) => {
    e.preventDefault()
    const ticker = searchInput.trim()
    if (ticker) {
      onSelectSecurity(ticker)
    }
  }

  const isSecurityMode = selectedSecurityKey !== null

  return (
    <Panel variant="mixed">
      <PanelHeader
        title="Lead Panel"
        subtitle={`Universe discovery -- ${movementLabel(movement)} x ${subjectLabel(subject)}, ranked server-side, read here, never re-derived`}
        timestamp={rankingQuery.data?.generated_at ?? null}
        source={
          subject === 'CHATTER' ? 'chatter axis (AMGT-rd-5)' : 'price axis (AMGT-rd-6)'
        }
        actions={
          <div className="flex items-center gap-3">
            {!isSecurityMode && (
              <>
                {/* CONTROL A -- independent of CONTROL B */}
                <Select
                  label="Movement"
                  value={movement}
                  options={MOVEMENT_OPTIONS}
                  onChange={(v) => setMovement(v as MovementControl)}
                />
                {/* CONTROL B -- independent of CONTROL A */}
                <Select
                  label="Subject"
                  value={subject}
                  options={SUBJECT_OPTIONS}
                  onChange={(v) => setSubject(v as SubjectControl)}
                />
                <button
                  type="button"
                  onClick={() => setStarredOnly(!starredOnly)}
                  aria-pressed={starredOnly}
                  className={`flex items-center gap-1.5 px-2.5 py-1.5 rounded-lg text-xs transition-colors ${
                    starredOnly
                      ? 'bg-amber-400/20 text-amber-300'
                      : 'bg-white/10 text-white/60 hover:bg-white/20'
                  }`}
                >
                  <Star size={12} className={starredOnly ? 'fill-amber-400 text-amber-400' : ''} />
                  Starred only
                </button>
                <div className="flex items-center gap-1 rounded-lg bg-white/10 p-1">
                  <button
                    type="button"
                    onClick={() => setView('list')}
                    className={`p-1.5 rounded ${view === 'list' ? 'bg-[hsl(var(--primary))] text-white' : 'text-white/60'}`}
                    aria-label="List view"
                  >
                    <LayoutList size={14} />
                  </button>
                  <button
                    type="button"
                    onClick={() => setView('chart')}
                    className={`p-1.5 rounded ${view === 'chart' ? 'bg-[hsl(var(--primary))] text-white' : 'text-white/60'}`}
                    aria-label="Chart view"
                  >
                    <ChartIcon size={14} />
                  </button>
                </div>
              </>
            )}
            <form onSubmit={handleSearchSubmit} className="flex items-center gap-1.5">
              <div className="relative">
                <Search size={12} className="absolute left-2 top-1/2 -translate-y-1/2 text-white/40" />
                <input
                  type="text"
                  value={searchInput}
                  onChange={(e) => setSearchInput(e.target.value)}
                  placeholder="Search any ticker"
                  className="pl-6 pr-2 py-1.5 rounded-lg bg-white/10 border border-white/20 text-white text-xs placeholder:text-white/30 focus:outline-none focus:ring-2 focus:ring-[hsl(var(--primary))] w-36"
                />
              </div>
            </form>
            {isSecurityMode && selectedSecurityKey && (
              <button
                type="button"
                onClick={() => refreshMutation.mutate(selectedSecurityKey)}
                disabled={refreshMutation.isPending}
                className="flex items-center gap-1.5 px-2.5 py-1.5 rounded-lg bg-white/10 text-white text-xs hover:bg-white/20 disabled:opacity-50 transition-colors"
              >
                <RefreshCw size={12} className={refreshMutation.isPending ? 'animate-spin' : ''} />
                Refresh
              </button>
            )}
          </div>
        }
      />
      <PanelContent>
        {isSecurityMode ? (
          <SecurityOverlay
            bundle={overlayQuery.data}
            isLoading={overlayQuery.isLoading}
            onClose={onClearSecuritySelection}
          />
        ) : (
          <>
            <ResolutionNote resolution={resolution} />
            {view === 'chart' ? (
              <RankedChart data={seriesQuery.data} isLoading={seriesQuery.isLoading} />
            ) : starredOnly ? (
              <StarredList
                rows={rows}
                starredTickers={starredTickers}
                resolution={resolution}
                onToggleStar={handleToggleStar}
                onSelectSecurity={onSelectSecurity}
                isLoading={rankingQuery.isLoading || starredQuery.isLoading}
              />
            ) : (
              <RankedList
                rows={rows}
                starredTickers={starredTickers}
                resolution={resolution}
                onToggleStar={handleToggleStar}
                onSelectSecurity={onSelectSecurity}
                isLoading={rankingQuery.isLoading}
              />
            )}
          </>
        )}
      </PanelContent>
    </Panel>
  )
}

