/**
 * ThesisTab -- REHOMED-FIGURES DESTINATION #1.
 *
 * The Model tab is CUT (task order BLOCK). Its figures rehome here (the full header +
 * fiscal-year model-block table, AMGT-s-1's `model_block_<security_key>.json`, with
 * AMGT-s-3's provenance line and AMGT-s-10's check-face verdict beside every value)
 * AND into the Lead Panel's Security overlay (`SecurityOverlay.tsx`, a condensed
 * header-figures-only view). See this cell's deliverable record, "WHERE each rehomed
 * figure went," for both destinations named together.
 *
 * Below the figures: the five drafted prose sections (AMGT-s-9), each machine
 * sentence visibly marked, evidence beside it, never behind a link.
 *
 * Dark-container-only (white idiom) -- the whole tab body is `Panel variant="mixed"`.
 */

import { type FC } from 'react'
import { Panel, PanelHeader, PanelContent } from '@/ui/components/panels'
import { useThesisBundle } from '../hooks/useLeadPanelApi'
import { ProvenanceLine } from '../components/ProvenanceLine'
import type { CheckFaceEntry, DraftedSection, ModelFigure } from '../types'

export interface ThesisTabProps {
  securityKey: string | null
}

function checkFor(checks: CheckFaceEntry[], figure: ModelFigure): CheckFaceEntry | undefined {
  const id = figure.fiscal_year != null ? `fy${figure.fiscal_year}:${figure.mnemonic}` : `header:${figure.mnemonic}`
  return checks.find((c) => c.figure_id === id)
}

function DraftedSectionBlock({ section }: { section: DraftedSection }) {
  return (
    <div className="space-y-2">
      <h4 className="text-xs font-semibold uppercase tracking-wide text-white/60">{section.label}</h4>
      {section.sentences.length === 0 ? (
        <p className="text-sm text-white/40 italic">
          Not drafted yet -- add your own.
        </p>
      ) : (
        <div className="space-y-1.5">
          {section.sentences.map((sentence, idx) => (
            <p
              key={idx}
              className={
                sentence.generated
                  ? 'text-sm text-white border-l-2 border-[hsl(var(--semantic-action-primary))] pl-2'
                  : 'text-sm text-white'
              }
              title={sentence.evidence ? `Evidence: ${sentence.evidence}` : undefined}
            >
              {sentence.generated && (
                <span className="text-[9px] uppercase tracking-wide text-[hsl(var(--semantic-action-primary))] mr-1.5">
                  machine
                </span>
              )}
              {sentence.text}
            </p>
          ))}
        </div>
      )}
    </div>
  )
}

export const ThesisTab: FC<ThesisTabProps> = ({ securityKey }) => {
  const { data, isLoading } = useThesisBundle(securityKey)

  if (!securityKey) {
    return (
      <Panel variant="mixed">
        <PanelContent>
          <p className="text-sm text-white/50 py-6 text-center">
            Select a name from the Lead Panel to open its Thesis.
          </p>
        </PanelContent>
      </Panel>
    )
  }

  return (
    <div className="space-y-4">
      <Panel variant="mixed">
        <PanelHeader title="Model figures" subtitle="Rehomed from the cut Model tab" timestamp={data?.generated_at ?? null} />
        <PanelContent>
          {isLoading && <p className="text-sm text-white/50">Loading...</p>}
          {!isLoading && data && (
            <div className="space-y-4">
              <div>
                <h4 className="text-xs font-semibold uppercase tracking-wide text-white/60 mb-1.5">Header</h4>
                <div className="space-y-1">
                  {data.header_figures.map((figure) => (
                    <ProvenanceLine
                      key={figure.mnemonic}
                      figure={figure}
                      verdict={checkFor(data.check_face, figure)?.verdict}
                      reason={checkFor(data.check_face, figure)?.reason}
                    />
                  ))}
                </div>
              </div>
              {data.fiscal_year_figures.length > 0 && (
                <div>
                  <h4 className="text-xs font-semibold uppercase tracking-wide text-white/60 mb-1.5">
                    Fiscal-year line items
                  </h4>
                  <div className="space-y-1 max-h-64 overflow-y-auto">
                    {data.fiscal_year_figures.map((figure) => (
                      <ProvenanceLine
                        key={`${figure.fiscal_year}:${figure.mnemonic}`}
                        figure={figure}
                        verdict={checkFor(data.check_face, figure)?.verdict}
                        reason={checkFor(data.check_face, figure)?.reason}
                      />
                    ))}
                  </div>
                </div>
              )}
            </div>
          )}
        </PanelContent>
      </Panel>

      <Panel variant="mixed">
        <PanelHeader title="Thesis" subtitle="Investment thesis -- machine sentences marked, evidence beside them" />
        <PanelContent>
          {isLoading && <p className="text-sm text-white/50">Loading...</p>}
          {!isLoading && data && (
            <div className="space-y-4">
              {data.drafted_sections.map((section) => (
                <DraftedSectionBlock key={section.section_id} section={section} />
              ))}
            </div>
          )}
        </PanelContent>
      </Panel>
    </div>
  )
}

