/**
 * SecurityAnalysis -- shared types.
 *
 * AMGT_RESAPP.TO-AMGT-rd-8 (round 5/v5, cell AMGT-rd-8, row S16, FWD-15).
 *
 * Every shape here is transcribed from a MEASURED artifact, never invented:
 *   - Lead Panel ranking rows: live `opal-harvest-security-metrics` read, 2026-09-11
 *     (`aws dynamodb query`/`scan --output json`, cited in this cell's deliverable
 *     record) + AMGT-rd-2's read-pattern record + AMGT-rd-5's window record +
 *     AMGT-rd-6's host record (`price_axis_rows_2026-09-10.json`). Table RENAMED
 *     ~20:1xZ the same session from `opal-amgt-security-metrics` (harvest-estate
 *     migration, 42 rows, full item equality) -- the dropped name no longer resolves;
 *     every shape below was re-verified against the renamed table before this cell's
 *     commit, not carried forward unchecked.
 *   - Starred marker rows: AMGT-rd-7's design record (`lib/research/watchlist/store.py`).
 *   - Model-block figures / provenance / check-face: AMGT-s-1/-s-3/-s-10's landed
 *     `model_block_<security_key>.json` / `check_face_<security_key>.json` shapes.
 *   - Coverage items / peer sets: AMGT-s-4 / AMGT-s-8's landed
 *     `coverage_items_<key>.json` / `peer_set_<key>.json` shapes.
 *
 * C-SERVER-SIDE-RANKING: `rank` and `rank_sort` are WRITTEN by the producer (AMGT-rd-5
 * chatter, AMGT-rd-6 price) at compute time. Nothing in this page's types or the hooks
 * that fetch them recomputes either field -- they are read, carried, and rendered in
 * the order the producer wrote them (ScanIndexForward=true on the GSI).
 */

// ---------------------------------------------------------------------------
// Lead Panel: TWO INDEPENDENT CONTROLS, crossed (AMGT-re-1 gap 1)
// ---------------------------------------------------------------------------

/** CONTROL A -- how the name is moving. Independent of the SUBJECT control
 * below; the panel is `(Trending | Breakout) x (Price | Chatter)`
 * (`AMGT_RESAPP_FRONTEND_FRAMEWORK_20260911.md` s.2, "TWO ORTHOGONAL AXES on
 * the Summary side ... the same four combinations Andrew named"). */
export type MovementControl = 'TRENDING' | 'BREAKOUT'

/** CONTROL B -- what is moving. The two subjects that have a server-side
 * producer, MEASURED live 2026-09-11 (`dynamodb scan --projection-expression
 * axis` over `opal-harvest-security-metrics`): {"CHATTER","PRICE"}. */
export type SubjectControl = 'CHATTER' | 'PRICE'

/** The FOUR combinations the two controls produce. Written as the cross of the
 * two control domains rather than as a hand-listed set of four strings, so a
 * member cannot go missing without one of the domains changing (Rule 24(i)).
 * The server's own enumeration is built the same way and by the same product --
 * `lib/research/api/scoped_amgt.py:CROSSED_AXES`. */
export type CrossedAxis = `${MovementControl}_${SubjectControl}`

/** What a ranking row's `axis` field may actually carry. Two populations, and
 * the union is a subtraction, not a guess: the SUBJECT-ONLY values a producer
 * writes TODAY (measured) plus the CROSSED values a producer will write once
 * the movement dimension is landed. Both are pre-computed, producer-written
 * partition identities -- neither is derived on this page. */
export type RankingAxis = SubjectControl | CrossedAxis

/** How a crossed request was actually served. A ranked payload can never arrive
 * without this record, so a reader is never shown a "Breakout" list that was in
 * fact served by the subject-only partition without being told
 * (CLAUDE.md: a value must carry its claim, in a field a consumer can reject on).
 *
 *   CROSSED               the producer has landed `<MOVEMENT>_<SUBJECT>#<date>`
 *                         and that partition served the read.
 *   SUBJECT_ONLY_FALLBACK it has not; the subject-only partition served instead
 *                         and the movement control is not yet discriminating. */
export interface AxisResolution {
  requested_axis: CrossedAxis
  served_axis: RankingAxis
  resolution: 'CROSSED' | 'SUBJECT_ONLY_FALLBACK'
  movement_basis: 'MEASURED' | 'ABSENT'
}

/** The SUBJECT half of any axis identity -- the one place a crossed or
 * subject-only axis is reduced to "chatter or price" for display and row
 * narrowing. Never touches `rank` or `score`. */
export function subjectOf(axis: RankingAxis): SubjectControl {
  return axis.endsWith('CHATTER') ? 'CHATTER' : 'PRICE'
}

/** One pre-computed row from `opal-harvest-security-metrics` (renamed from
 * `opal-amgt-security-metrics`, see module docstring), axis-rank-index GSI.
 * `rank`/`rank_sort` are producer-written; this page never recomputes them. */
export interface RankingRowBase {
  axis_date: string
  ticker: string
  axis: RankingAxis
  as_of_date: string
  computed_at: string
  rank: number
  rank_sort: string
  score: number
  window_days: number
  source?: string
}

/** CHATTER-subject row (AMGT-rd-5, `lib/research/metrics/chatter_gate.py`: 30-day
 * window, 0-100 normalized score, TOP_N=10). The discriminant is the whole
 * CHATTER column of the cross -- the subject-only partition a producer writes
 * today plus the two crossed partitions it will write. */
export interface ChatterRankingRow extends RankingRowBase {
  axis: 'CHATTER' | 'TRENDING_CHATTER' | 'BREAKOUT_CHATTER'
  raw_chatter_count: number
}

/** PRICE-subject row (AMGT-rd-6, `lib/research/price/axis.py`: 30-day window,
 * score = % price change over the window). */
export interface PriceRankingRow extends RankingRowBase {
  axis: 'PRICE' | 'TRENDING_PRICE' | 'BREAKOUT_PRICE'
  px_start_date: string
  px_start: number
  px_end_date: string
  px_end: number
  trading_days_observed: number
}

export type RankingRow = ChatterRankingRow | PriceRankingRow

export interface RankingSet {
  axis: RankingAxis
  /** How the crossed request was served -- carried on every ranked payload. */
  resolution: AxisResolution
  as_of_date: string
  /** Rows in PRODUCER order (rank ascending) -- never re-sorted client-side. */
  rows: RankingRow[]
  row_count: number
  generated_at: string
}

// ---------------------------------------------------------------------------
// Lead Panel: the CHART is over TIME (AMGT-re-1 gap 4)
// ---------------------------------------------------------------------------

/** One ticker's PRODUCER-WRITTEN rank/score at ONE `axis_date`. The chart's X
 * axis is `as_of_date`; nothing here is computed on load. */
export interface RankTimePoint {
  as_of_date: string
  rank: number
  rank_sort: string
  score: number
}

/** One ticker's series ACROSS `axis_date`. `point_count` is the honest
 * denominator: on the first day it is 1, and it becomes 2 the next day with no
 * code change, because AMGT-rd-5 writes a new `axis_date` daily. */
export interface TickerRankSeries {
  ticker: string
  points: RankTimePoint[]
  point_count: number
}

export interface RankTimeSeriesSet {
  resolution: AxisResolution
  as_of_date: string
  window_days: number
  series: TickerRankSeries[]
  generated_at: string
}

// ---------------------------------------------------------------------------
// Lead Panel: Starred (AMGT-rd-7, per-firm pure marker)
// ---------------------------------------------------------------------------

export interface StarredEntry {
  firm_id: string
  ticker: string
  starred: true
}

// ---------------------------------------------------------------------------
// Security identity (AMGT-s-12)
