/**
 * AMGT_RESAPP Lead Panel + Security Analysis API client -- the CLIENT HALF of the
 * `/api/scoped/amgt/*` adapters (AMGT_RESAPP.TO-AMGT-re-1, gap 2).
 *
 * THE SERVER HALF IS `lib/research/api/scoped_amgt.py`. Every function below has a
 * route in that module's `scoped_amgt_route_table()`, and that table is the
 * DENOMINATOR the two halves are diffed against: ten call functions here, eleven
 * routes there (`setStarred` is star-or-unstar).
 *
 * PRIVATE DATA, AUTH-GATED ON THE ESTATE'S OWN PATTERN, NOT A NEW ONE. `/api/scoped/*`
 * sits behind the CloudFront `auth-validator-edge` viewer-request Lambda@Edge, which
 * verifies the RS256 portal JWT and INJECTS the server-derived `X-Firm-Id` /
 * `X-User-Role` headers, overwriting whatever the client sent
 * (docs/architecture/PORTAL_AUTHHARD_PRD.md:21). Two consequences this file honours:
 *   - Every call goes through `apiRequest`, which attaches the bearer. No
 *     unauthenticated path is minted here.
 *   - THE FIRM IS NEVER SENT BY THE CLIENT. The watchlist routes take no firm
 *     segment and no firm body field; the server reads the firm from the injected
 *     header only. A firm id in a URL would be a filter, not a boundary.
 *
 * C-SERVER-SIDE-RANKING: every function returns rows in the order the DynamoDB
 * Query/GetItem/BatchGetItem call returned them (GSI `axis-rank-index`,
 * `ScanIndexForward: true`). Nothing in this file sorts, scores, or re-ranks.
 *
 * ROUTE DECLARATION, stated plainly: the API Gateway route + Lambda declaration that
 * mount `scoped_amgt.handler` live under `infra/aws/terraform/`, which is OUTSIDE this
 * cell's `<paths>` grant. The adapter code and its client are both delivered and
 * wired to each other; the route declaration is a separate surface with a separate
 * owner. Until it lands these calls 4xx at the edge and the page renders its stated
 * empty/refused states -- the same relationship `useScannerApi.ts` documents for
 * `security-scanner.ts`.
 */

import { apiRequest } from '@/api/api-client'
import type {
  MovementControl,
  SubjectControl,
  RankingSet,
  RankTimeSeriesSet,
  StarredEntry,
  SecurityOverlayBundle,
  ThesisBundle,
  PeerSet,
  CoverageSet,
} from '@/pages/SecurityAnalysis/types'

const BASE = '/api/scoped/amgt'

/** The crossed path segment pair. Two independent controls, two path segments --
 * a single "mode" segment here would be the one-to-one mapping the recut removes. */
function crossedPath(movement: MovementControl, subject: SubjectControl): string {
  return `${movement.toLowerCase()}/${subject.toLowerCase()}`
}

/**
 * THE RANKED READ, for ONE of the four combinations.
 *
 * `limit` maps to a DynamoDB `Limit` on the already-sorted GSI page -- trimming a
 * pre-sorted page, never sorting a larger read client-side (AMGT-rd-2's read-pattern
 * record, "Optionally bounded with Limit for a TOP_N view"). The returned
 * `RankingSet.resolution` states which partition actually served the read.
 */
export async function getLeadPanelRankings(
  movement: MovementControl,
  subject: SubjectControl,
  limit?: number
): Promise<RankingSet> {
  const qp = limit ? `?limit=${limit}` : ''
  return apiRequest<RankingSet>(`${BASE}/lead-panel/rankings/${crossedPath(movement, subject)}${qp}`)
}

/**
 * THE TIME SERIES: each named ticker's producer-written rank ACROSS `axis_date`.
 *
 * Server-side this is a BatchGetItem of point reads, one per (axis_date, ticker) --
 * no scan, no re-rank. One landed day yields one point per ticker; the second daily
 * run makes it a line with no code change here or there.
 */
export async function getRankTimeSeries(
  movement: MovementControl,
  subject: SubjectControl,
  tickers: string[],
  days?: number
): Promise<RankTimeSeriesSet> {
  const params = new URLSearchParams({ tickers: tickers.join(',') })
  if (days) params.set('days', String(days))
  return apiRequest<RankTimeSeriesSet>(
    `${BASE}/lead-panel/timeseries/${crossedPath(movement, subject)}?${params.toString()}`
  )
}

/** The firm's starred set (AMGT-rd-7, per-firm, pure marker). NO FIRM IN THE PATH:
 * the server reads it from the edge-injected `X-Firm-Id`, so this client cannot name
 * a firm even by accident. */
export async function getStarred(): Promise<StarredEntry[]> {
  return apiRequest<StarredEntry[]>(`${BASE}/watchlist`)
}

/** `star()`/`unstar()` are PURE MARKERS (AMGT-rd-7 bound) -- this call queues nothing
 * and triggers no refresh. Refresh (below) is deliberately a separate action. The
 * firm, again, is the server's to know. */
export async function setStarred(ticker: string, starred: boolean): Promise<void> {
  const action = starred ? 'star' : 'unstar'
  await apiRequest<void>(`${BASE}/watchlist/${action}`, {
    method: 'POST',
    body: JSON.stringify({ ticker }),
  })
}

/** Explicit Refresh action (queues the harvesters for one shown name). NOT wired to
 * starring -- Andrew-direct 2026-09-11 ~07:2xZ reversed the earlier star-triggers-
 * refresh design. The adapter refuses this route with a stated reason until a queue
 * carrier is declared; the button surfaces that refusal rather than pretending. */
export async function requestRefresh(securityKey: string): Promise<{ queued: boolean }> {
  return apiRequest<{ queued: boolean }>(`${BASE}/refresh`, {
    method: 'POST',
    body: JSON.stringify({ security_key: securityKey }),
  })
}

/** Security-mode overlay: header figures (rehomed from the cut Model tab) + this
 * ticker's CHATTER/PRICE point reads (GetItem per AMGT-rd-2's read-pattern record)
 * + its peer set. */
export async function getSecurityOverlay(securityKey: string): Promise<SecurityOverlayBundle> {
  return apiRequest<SecurityOverlayBundle>(`${BASE}/security/${encodeURIComponent(securityKey)}/overlay`)
}

/** Thesis tab bundle: header + fiscal-year model figures (rehomed), check-face, and
 * the drafted prose sections. */
export async function getThesisBundle(securityKey: string): Promise<ThesisBundle> {
  return apiRequest<ThesisBundle>(`${BASE}/security/${encodeURIComponent(securityKey)}/thesis`)
}

/** Peers tab (AMGT-s-8): exactly one of analyst/derived/absent, never a bare list. */
export async function getPeerSet(securityKey: string): Promise<PeerSet> {
  return apiRequest<PeerSet>(`${BASE}/security/${encodeURIComponent(securityKey)}/peers`)
}

/** Coverage tab (AMGT-s-4 + C-AMGT-ARTICLES-STORE): MEASURED empty today
 * (`opal-harvest-articles` 0 items, 2026-09-11) -- an empty `items` array here is a
 * real, honest state the tab must render, never an error. */
export async function getCoverageSet(securityKey: string): Promise<CoverageSet> {
  return apiRequest<CoverageSet>(`${BASE}/security/${encodeURIComponent(securityKey)}/coverage`)
}

/** The print route this action calls -- exported so the render check can assert the
 * REAL action hits the REAL path, rather than re-typing the string beside it. */
export function printPackPath(securityKey: string): string {
  return `${BASE}/security/${encodeURIComponent(securityKey)}/print`
}

/** Print header action (AMGT-s-5's `render_pack.py`, not a tab): requests the
 * server-side PDF and returns the raw bytes for the preview modal.
 * NOT `apiRequest` -- that helper always calls `response.json()`, which would break
 * on a binary PDF body, so this repeats only its auth-header shape for a `.blob()`
 * response (same token read `api-client.ts` uses: `localStorage.getItem('accessToken')`). */
export async function requestPrintPack(securityKey: string): Promise<Blob> {
  const accessToken = localStorage.getItem('accessToken')
  const response = await fetch(printPackPath(securityKey), {
    headers: {
      ...(accessToken && { Authorization: `Bearer ${accessToken}` }),
    },
  })
  if (!response.ok) {
    throw new Error(`Print pack request failed: ${response.status} ${response.statusText}`)
  }
  return response.blob()
}
